	var total int64
	for _, e := range l.entries {
		if e.Account != account {
			continue
		}
		total += e.Amount
	}
	if cached, ok := l.balances[account]; ok && cached != total {
		panic(fmt.Sprintf("ledger: balance cache drift for %s: %d != %d", account, cached, total))
	}
	return total
}

