27	func quarterBounds(year, quarter int) (time.Time, time.Time) {
28		start := time.Date(year, time.Month((quarter-1)*3+1), 1, 0, 0, 0, 0, time.UTC)
29		return start, start.AddDate(0, 3, 0)
30	}
